var HJ_DOA = {
  talbiah:{t:["Talbiah","Talbiyah"], ar:"لَبَّيْكَ اللّٰهُمَّ لَبَّيْكَ، لَبَّيْكَ لَا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ وَالْمُلْكَ، لَا شَرِيكَ لَكَ",
    r:"Labbaikallahumma labbaik, labbaika la syarika laka labbaik, innal hamda wan ni'mata laka wal mulk, la syarika lak.",
    m:["Aku datang memenuhi panggilan-Mu ya Allah, aku datang. Aku datang, tiada sekutu bagi-Mu, aku datang. Sesungguhnya segala puji, nikmat dan kerajaan adalah milik-Mu. Tiada sekutu bagi-Mu.","Here I am, O Allah, here I am. Here I am, You have no partner, here I am. All praise, blessing and dominion belong to You. You have no partner."],
    s:"Sahih al-Bukhari 1549; Sahih Muslim 1184"},
  selawat:{t:["Selawat selepas talbiah","Salawat after the talbiyah"], ar:"اللّٰهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ",
    r:"Allahumma solli 'ala Muhammad wa 'ala ali Muhammad.",
    m:["Ya Allah, limpahkanlah selawat ke atas Nabi Muhammad dan keluarga Nabi Muhammad.","O Allah, send blessings upon Muhammad and the family of Muhammad."], s:"Sahih al-Bukhari 3370 (sebahagian selawat Ibrahimiyah)"},
  ridha:{t:["Doa selepas talbiah","Doa after the talbiyah"], ar:"اللّٰهُمَّ إِنِّي أَسْأَلُكَ رِضَاكَ وَالْجَنَّةَ، وَأَعُوذُ بِكَ مِنْ سَخَطِكَ وَالنَّارِ",
    r:"Allahumma inni as'aluka ridhaka wal jannah, wa a'uzu bika min sakhatika wan nar.",
    m:["Ya Allah, aku memohon keredaan-Mu dan syurga, dan aku berlindung dengan-Mu daripada kemurkaan-Mu dan neraka.","O Allah, I ask You for Your pleasure and Paradise, and I seek refuge in You from Your anger and the Fire."], s:"Disebut oleh Imam asy-Syafi'i dalam al-Umm"},
  niat_u:{t:["Niat umrah","Niat for umrah"], ar:"نَوَيْتُ الْعُمْرَةَ وَأَحْرَمْتُ بِهَا لِلّٰهِ تَعَالَى، لَبَّيْكَ اللّٰهُمَّ عُمْرَةً",
    r:"Nawaitul 'umrata wa ahramtu biha lillahi ta'ala. Labbaikallahumma 'umrah.",
    m:["Sahaja aku berniat umrah dan berihram dengannya kerana Allah Taala. Aku datang ya Allah untuk umrah.","I intend umrah and enter ihram for it for the sake of Allah. Here I am, O Allah, for umrah."], s:"Lafaz niat mazhab Syafi'i (niat di hati sudah memadai)"},
  niat_h:{t:["Niat haji","Niat for hajj"], ar:"نَوَيْتُ الْحَجَّ وَأَحْرَمْتُ بِهِ لِلّٰهِ تَعَالَى، لَبَّيْكَ اللّٰهُمَّ حَجًّا",
    r:"Nawaitul hajja wa ahramtu bihi lillahi ta'ala. Labbaikallahumma hajja.",
    m:["Sahaja aku berniat haji dan berihram dengannya kerana Allah Taala. Aku datang ya Allah untuk haji.","I intend hajj and enter ihram for it for the sake of Allah. Here I am, O Allah, for hajj."], s:"Lafaz niat mazhab Syafi'i (niat di hati sudah memadai)"},
  niat_q:{t:["Niat haji qiran","Niat for hajj qiran"], ar:"نَوَيْتُ الْحَجَّ وَالْعُمْرَةَ وَأَحْرَمْتُ بِهِمَا لِلّٰهِ تَعَالَى، لَبَّيْكَ اللّٰهُمَّ عُمْرَةً وَحَجًّا",
    r:"Nawaitul hajja wal 'umrata wa ahramtu bihima lillahi ta'ala. Labbaikallahumma 'umratan wa hajja.",
    m:["Sahaja aku berniat haji dan umrah serta berihram dengan kedua-duanya kerana Allah Taala.","I intend hajj and umrah together and enter ihram for both for the sake of Allah."], s:"Sahih Muslim 1251 (lafaz talbiah qiran)"},
  solat_ihram:{t:["Niat solat sunat ihram","Niat for the ihram prayer"], ar:"أُصَلِّي سُنَّةَ الْإِحْرَامِ رَكْعَتَيْنِ لِلّٰهِ تَعَالَى",
    r:"Usolli sunnatal ihrami rak'ataini lillahi ta'ala.",
    m:["Sahaja aku solat sunat ihram dua rakaat kerana Allah Taala.","I pray two rakaat of the sunnah of ihram for the sake of Allah."], s:"Fiqh mazhab Syafi'i"},
  masuk:{t:["Doa masuk masjid","Doa entering the mosque"], ar:"بِسْمِ اللّٰهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللّٰهِ، اللّٰهُمَّ افْتَحْ لِي أَبْوَابَ رَحْمَتِكَ",
    r:"Bismillah, wassolatu wassalamu 'ala Rasulillah. Allahummaftah li abwaba rahmatik.",
    m:["Dengan nama Allah, selawat dan salam ke atas Rasulullah. Ya Allah, bukakanlah untukku pintu-pintu rahmat-Mu.","In the name of Allah, blessings and peace be upon the Messenger of Allah. O Allah, open for me the doors of Your mercy."], s:"Sahih Muslim 713; Sunan Ibn Majah 771"},
  keluar:{t:["Doa keluar masjid","Doa leaving the mosque"], ar:"بِسْمِ اللّٰهِ، وَالصَّلَاةُ وَالسَّلَامُ عَلَى رَسُولِ اللّٰهِ، اللّٰهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ",
    r:"Bismillah, wassolatu wassalamu 'ala Rasulillah. Allahumma inni as'aluka min fadhlik.",
    m:["Dengan nama Allah, selawat dan salam ke atas Rasulullah. Ya Allah, aku memohon kurniaan-Mu.","In the name of Allah, blessings and peace be upon the Messenger of Allah. O Allah, I ask You of Your bounty."], s:"Sahih Muslim 713; Sunan Ibn Majah 771"},
  lihat_kaabah:{t:["Doa melihat Kaabah","Doa on seeing the Kaabah"], ar:"اللّٰهُمَّ زِدْ هٰذَا الْبَيْتَ تَشْرِيفًا وَتَعْظِيمًا وَتَكْرِيمًا وَمَهَابَةً، وَزِدْ مَنْ شَرَّفَهُ وَكَرَّمَهُ مِمَّنْ حَجَّهُ أَوِ اعْتَمَرَهُ تَشْرِيفًا وَتَكْرِيمًا وَتَعْظِيمًا وَبِرًّا",
    r:"Allahumma zid hazal baita tasyrifan wa ta'ziman wa takriman wa mahabah, wa zid man syarrafahu wa karramahu mimman hajjahu awi'tamarahu tasyrifan wa takriman wa ta'ziman wa birra.",
    m:["Ya Allah, tambahkanlah kemuliaan, keagungan, kehormatan dan kehebatan rumah ini. Tambahkanlah juga kemuliaan, kehormatan, keagungan dan kebaikan kepada sesiapa yang memuliakannya daripada kalangan yang menunaikan haji atau umrah.","O Allah, increase this House in honour, greatness, respect and awe, and increase those who honour it among the pilgrims of hajj and umrah in honour, respect, greatness and goodness."],
    s:"Al-Baihaqi, as-Sunan al-Kubra (mursal); al-Umm, Imam asy-Syafi'i"},
  niat_tawaf:{t:["Niat tawaf","Niat for tawaf"], ar:"نَوَيْتُ الطَّوَافَ سَبْعَةَ أَشْوَاطٍ لِلّٰهِ تَعَالَى",
    r:"Nawaitut tawafa sab'ata asywatin lillahi ta'ala.",
    m:["Sahaja aku tawaf tujuh pusingan kerana Allah Taala.","I intend seven rounds of tawaf for the sake of Allah."], s:"Fiqh mazhab Syafi'i"},
  istilam:{t:["Mula setiap pusingan di Hajar Aswad","Start each round at the Black Stone"], ar:"بِسْمِ اللّٰهِ وَاللّٰهُ أَكْبَرُ",
    r:"Bismillahi wallahu akbar.",
    m:["Dengan nama Allah, dan Allah Maha Besar. Angkat tangan kanan ke arah Hajar Aswad, kemudian kucup tangan itu.","In the name of Allah, and Allah is the Greatest. Raise your right hand towards the Black Stone, then kiss your hand."],
    s:"Sahih al-Bukhari 1613 (takbir di sudut Hajar Aswad); al-Baihaqi (Ibn 'Umar)"},
  rabbana:{t:["Antara Rukun Yamani dan Hajar Aswad","Between the Yamani corner and the Black Stone"], ar:"رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ",
    r:"Rabbana atina fid dunya hasanah, wa fil akhirati hasanah, wa qina 'azaban nar.",
    m:["Wahai Tuhan kami, kurniakanlah kami kebaikan di dunia dan kebaikan di akhirat, dan peliharalah kami daripada azab neraka.","Our Lord, give us good in this world and good in the Hereafter, and protect us from the punishment of the Fire."],
    s:"Sunan Abi Dawud 1892; al-Baqarah 2:201"},
  afiyah:{t:["Doa memohon keampunan dan kesejahteraan","Doa for pardon and wellbeing"], ar:"اللّٰهُمَّ إِنِّي أَسْأَلُكَ الْعَفْوَ وَالْعَافِيَةَ فِي الدُّنْيَا وَالْآخِرَةِ",
    r:"Allahumma inni as'alukal 'afwa wal 'afiyah fid dunya wal akhirah.",
    m:["Ya Allah, aku memohon kemaafan dan kesejahteraan di dunia dan di akhirat.","O Allah, I ask You for pardon and wellbeing in this world and the Hereafter."], s:"Sunan Abi Dawud 5074; Sunan Ibn Majah 3871"},
  maqam:{t:["Ayat di Maqam Ibrahim","The verse at Maqam Ibrahim"], ar:"وَاتَّخِذُوا مِنْ مَقَامِ إِبْرَاهِيمَ مُصَلًّى",
    r:"Wattakhizu min maqami Ibrahima musolla.",
    m:["Dan jadikanlah Maqam Ibrahim itu tempat solat.","And take the standing place of Ibrahim as a place of prayer."], s:"Al-Baqarah 2:125; Sahih Muslim 1218"},
  solat_tawaf:{t:["Niat solat sunat tawaf","Niat for the tawaf prayer"], ar:"أُصَلِّي سُنَّةَ الطَّوَافِ رَكْعَتَيْنِ لِلّٰهِ تَعَالَى",
    r:"Usolli sunnatat tawafi rak'ataini lillahi ta'ala.",
    m:["Sahaja aku solat sunat tawaf dua rakaat kerana Allah Taala. Rakaat pertama baca al-Kafirun, rakaat kedua al-Ikhlas.","I pray two rakaat of the tawaf sunnah for the sake of Allah. Recite al-Kafirun in the first rakaat and al-Ikhlas in the second."], s:"Sahih Muslim 1218"},
  zamzam:{t:["Doa minum air Zamzam","Doa when drinking Zamzam"], ar:"اللّٰهُمَّ إِنِّي أَسْأَلُكَ عِلْمًا نَافِعًا، وَرِزْقًا وَاسِعًا، وَشِفَاءً مِنْ كُلِّ دَاءٍ",
    r:"Allahumma inni as'aluka 'ilman nafi'a, wa rizqan wasi'a, wa syifa'an min kulli da'.",
    m:["Ya Allah, aku memohon ilmu yang bermanfaat, rezeki yang luas dan penyembuhan daripada segala penyakit.","O Allah, I ask You for beneficial knowledge, plentiful provision and a cure from every illness."], s:"Ad-Daraqutni (Ibn 'Abbas); \"Air Zamzam menurut niat peminumnya\": Sunan Ibn Majah 3062"},
  safa:{t:["Ketika naik Bukit Safa","Climbing Mount Safa"], ar:"إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللّٰهِ، أَبْدَأُ بِمَا بَدَأَ اللّٰهُ بِهِ",
    r:"Innas Safa wal Marwata min sya'a'irillah. Abda'u bima bada'allahu bih.",
    m:["Sesungguhnya Safa dan Marwah adalah antara syiar Allah. Aku mulakan dengan apa yang Allah mulakan.","Indeed Safa and Marwah are among the signs of Allah. I begin with what Allah began with."], s:"Al-Baqarah 2:158; Sahih Muslim 1218"},
  safa_zikir:{t:["Zikir di atas Safa dan Marwah","Dhikr on Safa and Marwah"], ar:"اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ. لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ، أَنْجَزَ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الْأَحْزَابَ وَحْدَهُ",
    r:"Allahu akbar, Allahu akbar, Allahu akbar. La ilaha illallahu wahdahu la syarika lah, lahul mulku wa lahul hamd, wa huwa 'ala kulli syai'in qadir. La ilaha illallahu wahdah, anjaza wa'dah, wa nasara 'abdah, wa hazamal ahzaba wahdah.",
    m:["Allah Maha Besar (3 kali). Tiada Tuhan melainkan Allah, Yang Esa, tiada sekutu bagi-Nya; milik-Nya kerajaan dan pujian, dan Dia berkuasa atas segala sesuatu. Tiada Tuhan melainkan Allah Yang Esa; Dia menunaikan janji-Nya, menolong hamba-Nya dan mengalahkan tentera bersekutu dengan sendiri-Nya. Hadap Kaabah, angkat tangan, ulang tiga kali dan berdoa di antaranya.","Allah is the Greatest (3 times). There is no god but Allah alone, without partner; His is the dominion and the praise, and He has power over all things. There is no god but Allah alone; He fulfilled His promise, helped His servant and defeated the confederates alone. Face the Kaabah, raise your hands, repeat three times and make doa in between."],
    s:"Sahih Muslim 1218"},
  hijau:{t:["Di antara lampu hijau","Between the green lights"], ar:"رَبِّ اغْفِرْ وَارْحَمْ، إِنَّكَ أَنْتَ الْأَعَزُّ الْأَكْرَمُ",
    r:"Rabbighfir warham, innaka antal a'azzul akram.",
    m:["Wahai Tuhanku, ampunkanlah dan rahmatilah. Sesungguhnya Engkau Maha Perkasa lagi Maha Pemurah.","My Lord, forgive and have mercy. You are the Most Mighty, the Most Generous."], s:"Ibn Abi Syaibah, al-Musannaf (Ibn Mas'ud dan Ibn 'Umar)"},
  cukur:{t:["Doa Nabi ﷺ untuk yang bercukur","The Prophet's ﷺ doa for those who shave"], ar:"اللّٰهُمَّ ارْحَمِ الْمُحَلِّقِينَ، قَالُوا: وَالْمُقَصِّرِينَ؟ قَالَ: وَالْمُقَصِّرِينَ",
    r:"Allahummarhamil muhalliqin. Qalu: wal muqassirin? Qala: wal muqassirin.",
    m:["\"Ya Allah, rahmatilah orang yang bercukur.\" Sahabat bertanya: \"Dan yang bergunting?\" Baginda menjawab: \"Dan yang bergunting.\" Bertakbirlah semasa bercukur.","\"O Allah, have mercy on those who shave.\" They asked: \"And those who trim?\" He said: \"And those who trim.\" Say takbir while your hair is cut."], s:"Sahih al-Bukhari 1727; Sahih Muslim 1301"},
  arafah:{t:["Doa terbaik di hari Arafah","The best doa on the day of Arafah"], ar:"لَا إِلٰهَ إِلَّا اللّٰهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ",
    r:"La ilaha illallahu wahdahu la syarika lah, lahul mulku wa lahul hamd, wa huwa 'ala kulli syai'in qadir.",
    m:["Tiada Tuhan melainkan Allah Yang Esa, tiada sekutu bagi-Nya. Milik-Nya kerajaan dan pujian, dan Dia berkuasa atas segala sesuatu.","There is no god but Allah alone, without partner. His is the dominion and the praise, and He has power over all things."], s:"Sunan at-Tirmizi 3585"},
  istighfar:{t:["Istighfar","Seeking forgiveness"], ar:"أَسْتَغْفِرُ اللّٰهَ الْعَظِيمَ الَّذِي لَا إِلٰهَ إِلَّا هُوَ الْحَيُّ الْقَيُّومُ وَأَتُوبُ إِلَيْهِ",
    r:"Astaghfirullahal 'azim, allazi la ilaha illa huwal hayyul qayyum, wa atubu ilaih.",
    m:["Aku memohon ampun kepada Allah Yang Maha Agung, tiada Tuhan melainkan Dia, Yang Maha Hidup lagi Maha Berdiri Sendiri, dan aku bertaubat kepada-Nya.","I seek forgiveness from Allah the Magnificent, there is no god but He, the Ever-Living, the Sustainer, and I repent to Him."], s:"Sunan Abi Dawud 1517; Sunan at-Tirmizi 3577"},
  masyar:{t:["Zikir di Masy'aril Haram","Dhikr at al-Mash'ar al-Haram"], ar:"فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ فَاذْكُرُوا اللّٰهَ عِنْدَ الْمَشْعَرِ الْحَرَامِ",
    r:"Fa iza afadhtum min 'arafatin fazkurullaha 'indal masy'aril haram.",
    m:["Apabila kamu bertolak dari Arafah, berzikirlah kepada Allah di Masy'aril Haram. Hadap kiblat, bertakbir, bertahlil dan berdoa hingga langit cerah.","When you depart from Arafah, remember Allah at al-Mash'ar al-Haram. Face the qibla, say takbir and tahlil, and make doa until the sky is bright."], s:"Al-Baqarah 2:198; Sahih Muslim 1218"},
  lontar:{t:["Setiap kali melontar","With every pebble"], ar:"بِسْمِ اللّٰهِ، اللّٰهُ أَكْبَرُ",
    r:"Bismillah, Allahu akbar.",
    m:["Dengan nama Allah, Allah Maha Besar. Lontar satu demi satu, tujuh biji.","In the name of Allah, Allah is the Greatest. Throw them one by one, seven pebbles."], s:"Takbir setiap batu: Sahih al-Bukhari 1751; Sahih Muslim 1218"},
  takbir:{t:["Takbir hari raya","Eid takbir"], ar:"اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ، لَا إِلٰهَ إِلَّا اللّٰهُ، وَاللّٰهُ أَكْبَرُ، اللّٰهُ أَكْبَرُ وَلِلّٰهِ الْحَمْدُ",
    r:"Allahu akbar, Allahu akbar, Allahu akbar, la ilaha illallahu wallahu akbar, Allahu akbar wa lillahil hamd.",
    m:["Allah Maha Besar (3 kali), tiada Tuhan melainkan Allah, Allah Maha Besar, Allah Maha Besar dan bagi Allah segala puji.","Allah is the Greatest (3 times), there is no god but Allah, Allah is the Greatest, Allah is the Greatest and to Allah belongs all praise."], s:"Ibn Abi Syaibah, al-Musannaf (Ibn Mas'ud)"},
  sembelih:{t:["Ketika menyembelih","When slaughtering"], ar:"بِسْمِ اللّٰهِ وَاللّٰهُ أَكْبَرُ",
    r:"Bismillahi wallahu akbar.",
    m:["Dengan nama Allah, dan Allah Maha Besar.","In the name of Allah, and Allah is the Greatest."], s:"Sahih Muslim 1966"},
  safar:{t:["Doa naik kenderaan","Doa for travelling"], ar:"سُبْحَانَ الَّذِي سَخَّرَ لَنَا هٰذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ، وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ",
    r:"Subhanallazi sakhkhara lana haza wa ma kunna lahu muqrinin, wa inna ila rabbina lamunqalibun.",
    m:["Maha Suci Allah yang menundukkan kenderaan ini untuk kami, padahal kami tidak mampu menguasainya. Dan sesungguhnya kepada Tuhan kamilah kami akan kembali.","Glory be to the One who made this subservient to us, though we could not have done so ourselves. And to our Lord we will surely return."], s:"Az-Zukhruf 43:13-14; Sahih Muslim 1342"},
  salam_nabi:{t:["Salam kepada Rasulullah ﷺ","Greeting the Prophet ﷺ"], ar:"السَّلَامُ عَلَيْكَ يَا رَسُولَ اللّٰهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللّٰهِ وَبَرَكَاتُهُ",
    r:"Assalamu 'alaika ya Rasulallah. Assalamu 'alaika ayyuhan nabiyyu wa rahmatullahi wa barakatuh.",
    m:["Salam sejahtera ke atasmu wahai Rasulullah. Salam sejahtera ke atasmu wahai Nabi, serta rahmat Allah dan keberkatan-Nya.","Peace be upon you, O Messenger of Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings."], s:"Amalan Ibn 'Umar r.a. (Malik, al-Muwatta'; al-Baihaqi)"},
  salam_sahabat:{t:["Salam kepada Abu Bakar dan Umar r.a.","Greeting Abu Bakr and Umar"], ar:"السَّلَامُ عَلَيْكَ يَا أَبَا بَكْرٍ، السَّلَامُ عَلَيْكَ يَا عُمَرُ",
    r:"Assalamu 'alaika ya Aba Bakr. Assalamu 'alaika ya 'Umar.",
    m:["Salam sejahtera ke atasmu wahai Abu Bakar. Salam sejahtera ke atasmu wahai Umar.","Peace be upon you, O Abu Bakr. Peace be upon you, O Umar."], s:"Amalan Ibn 'Umar r.a. (Malik, al-Muwatta'; al-Baihaqi)"},
  raudhah:{t:["Sabda Nabi ﷺ tentang Raudhah","The Prophet's ﷺ words on the Raudhah"], ar:"مَا بَيْنَ بَيْتِي وَمِنْبَرِي رَوْضَةٌ مِنْ رِيَاضِ الْجَنَّةِ",
    r:"Ma baina baiti wa minbari raudhatun min riyadhil jannah.",
    m:["Kawasan di antara rumahku dan mimbarku adalah satu taman daripada taman-taman syurga.","What is between my house and my pulpit is one of the gardens of Paradise."], s:"Sahih al-Bukhari 1196; Sahih Muslim 1391"},
  kubur:{t:["Doa ziarah kubur","Doa when visiting graves"], ar:"السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللّٰهُ بِكُمْ لَلَاحِقُونَ، أَسْأَلُ اللّٰهَ لَنَا وَلَكُمُ الْعَافِيَةَ",
    r:"Assalamu 'alaikum ahlad diyari minal mu'minina wal muslimin, wa inna in sya Allahu bikum lalahiqun, as'alullaha lana wa lakumul 'afiyah.",
    m:["Salam sejahtera ke atas kamu wahai penghuni kubur daripada kalangan mukmin dan muslim. Kami, insya-Allah, akan menyusul kamu. Aku memohon kepada Allah kesejahteraan untuk kami dan kamu.","Peace be upon you, people of these dwellings, believers and Muslims. We will, if Allah wills, join you. I ask Allah for wellbeing for us and for you."], s:"Sahih Muslim 975"},
  quba:{t:["Kelebihan solat di Masjid Quba","The virtue of praying at Quba"], ar:"مَنْ تَطَهَّرَ فِي بَيْتِهِ ثُمَّ أَتَى مَسْجِدَ قُبَاءَ فَصَلَّى فِيهِ صَلَاةً كَانَ لَهُ كَأَجْرِ عُمْرَةٍ",
    r:"Man tatahhara fi baitihi tsumma ata masjida Quba'a fasolla fihi solatan kana lahu ka-ajri 'umrah.",
    m:["Sesiapa yang bersuci di rumahnya, kemudian datang ke Masjid Quba dan solat di dalamnya, baginya pahala seperti umrah.","Whoever purifies himself at home, then comes to Quba Mosque and prays in it, has a reward like that of umrah."], s:"Sunan Ibn Majah 1412"},
  nabawi:{t:["Kelebihan solat di Masjid Nabawi","The virtue of praying in the Prophet's Mosque"], ar:"صَلَاةٌ فِي مَسْجِدِي هٰذَا خَيْرٌ مِنْ أَلْفِ صَلَاةٍ فِيمَا سِوَاهُ إِلَّا الْمَسْجِدَ الْحَرَامَ",
    r:"Solatun fi masjidi haza khairun min alfi solatin fima siwahu illal masjidal haram.",
    m:["Solat di masjidku ini lebih baik daripada seribu solat di masjid lain, kecuali Masjidil Haram.","A prayer in this mosque of mine is better than a thousand prayers elsewhere, except al-Masjid al-Haram."], s:"Sahih al-Bukhari 1190; Sahih Muslim 1394"},
  wada:{t:["Sabda Nabi ﷺ tentang tawaf wada'","The Prophet's ﷺ words on the farewell tawaf"], ar:"لَا يَنْفِرَنَّ أَحَدٌ حَتَّى يَكُونَ آخِرُ عَهْدِهِ بِالْبَيْتِ",
    r:"La yanfiranna ahadun hatta yakuna akhiru 'ahdihi bil bait.",
    m:["Janganlah seseorang meninggalkan (Makkah) sehingga akhir urusannya ialah dengan Baitullah (tawaf).","Let no one leave until his last act is at the House (tawaf)."], s:"Sahih Muslim 1327"},
  hijr:{t:["Hijir Ismail sebahagian Kaabah","Hijr Ismail is part of the Kaabah"], ar:"صَلِّي فِي الْحِجْرِ إِنْ أَرَدْتِ دُخُولَ الْبَيْتِ، فَإِنَّمَا هُوَ قِطْعَةٌ مِنَ الْبَيْتِ",
    r:"Solli fil hijri in aradti dukhulal bait, fa innama huwa qit'atun minal bait.",
    m:["Solatlah di Hijir jika engkau mahu masuk ke dalam Baitullah, kerana ia sebahagian daripada Baitullah. Maka tawaf mesti di luar Hijir Ismail.","Pray in the Hijr if you wish to enter the House, for it is part of the House. So tawaf must go around the outside of the Hijr."], s:"Sunan at-Tirmizi 876; Sunan Abi Dawud 2028"}
};

// k: R rukun, W wajib, S sunat, A adab/info, D dam. act: practice action.
var HJ_STEPS = {
  // ---------- Miqat & ihram ----------
  miqat5:{pl:"miqat", k:"W", t:["Lima miqat","The five miqat"],
    d:["Miqat ialah sempadan tempat kita mesti berniat ihram sebelum melepasinya. Ada lima miqat yang ditetapkan oleh Nabi ﷺ. Jemaah Malaysia yang terbang terus ke Jeddah berniat di udara ketika melintasi Qarnul Manazil (juruterbang akan memaklumkan). Yang ke Madinah dahulu berniat di Bir Ali. Penduduk Makkah berniat dari Makkah untuk haji, dan dari tanah halal seperti Tan'im untuk umrah.","A miqat is the boundary where you must make niat for ihram before crossing it. The Prophet ﷺ set five of them. Malaysians flying straight to Jeddah make niat in the air over Qarn al-Manazil (the crew will announce it). Those going to Madinah first make niat at Bir Ali. People already in Makkah make niat in Makkah for hajj, and outside the Haram (such as Tan'im) for umrah."],
    w:["Sebelum melepasi miqat","Before crossing the miqat"], tip:[["Melepasi miqat tanpa ihram dan tidak kembali: wajib dam.","Crossing the miqat without ihram and not going back: dam is due."]], src:"Sahih al-Bukhari 1524; Sahih Muslim 1181"},
  prep:{pl:"birali", k:"S", t:["Bersiap untuk ihram","Getting ready for ihram"],
    d:["Mandi sunat ihram, potong kuku, rapikan rambut dan pakai wangian pada badan (bukan pada kain ihram) sebelum berniat. Lelaki memakai dua helai kain putih tidak berjahit: satu dililit di pinggang, satu diselempang di bahu, dan selipar yang menampakkan buku lali. Wanita memakai pakaian biasa yang menutup aurat, longgar dan tidak menarik perhatian; muka dan tapak tangan terbuka.","Take the ihram bath, trim your nails, tidy your hair and put perfume on your body (not on the ihram cloth) before niat. Men wear two plain white unstitched sheets, one wrapped around the waist and one over the shoulders, with sandals that show the ankles. Women wear their normal loose clothes that cover the aurat; the face and palms stay uncovered."],
    w:["Sebelum berniat di miqat","Before niat at the miqat"], act:"ihram", src:"Sahih al-Bukhari 1539; Sunan at-Tirmizi 830"},
  solatihram:{pl:"birali", k:"S", t:["Solat sunat ihram","The ihram prayer"],
    d:["Solat dua rakaat sunat ihram jika bukan waktu yang dilarang. Rakaat pertama baca al-Kafirun, rakaat kedua al-Ikhlas. Jika baru selesai solat fardu, ia sudah memadai.","Pray two rakaat for ihram if it is not a disliked time. Recite al-Kafirun in the first and al-Ikhlas in the second. If you have just prayed a fard prayer, that is enough."],
    sl:["2 rakaat sunat ihram","2 rakaat ihram sunnah"], w:["Sebelum berniat","Before niat"], doa:["solat_ihram"], act:"solat"},
  niat_u:{pl:"birali", k:"R", t:["Niat ihram umrah","Niat for umrah ihram"],
    d:["Niat ihram ialah rukun pertama. Selepas berniat, kita dalam ihram dan semua larangan ihram terpakai. Lafazkan niat, kemudian mula bertalbiah.","The niat of ihram is the first rukun. After it you are in ihram and all the ihram rules apply. Say the niat, then start the talbiyah."],
    w:["Di miqat, sebelum melepasinya","At the miqat, before crossing it"], doa:["niat_u","talbiah"]},
  niat_h:{pl:"birali", k:"R", t:["Niat ihram haji (ifrad)","Niat for hajj ihram (ifrad)"],
    d:["Haji ifrad: berniat haji sahaja di miqat. Kita kekal dalam ihram sehingga selesai haji. Umrah dibuat selepas haji.","Hajj ifrad: make niat for hajj only at the miqat. You stay in ihram until the hajj is done. Umrah is done after the hajj."],
    w:["Di miqat, dalam bulan haji (Syawal, Zulkaedah, 1 hingga 10 Zulhijjah)","At the miqat, in the hajj months (Syawwal, Dhul Qa'dah, 1 to 10 Dhul Hijjah)"], doa:["niat_h","talbiah"]},
  niat_q:{pl:"birali", k:"R", t:["Niat ihram haji qiran","Niat for hajj qiran"],
    d:["Haji qiran: berniat haji dan umrah serentak di miqat. Amalan haji meliputi umrah sekali, dan wajib dam.","Hajj qiran: make niat for hajj and umrah together at the miqat. The hajj rites cover the umrah too, and dam is due."],
    w:["Di miqat, dalam bulan haji","At the miqat, in the hajj months"], doa:["niat_q","talbiah"]},
  talbiah:{pl:"birali", k:"S", t:["Bertalbiah","Saying the talbiyah"],
    d:["Lelaki menguatkan suara, wanita memperlahankan. Ulang sepanjang perjalanan, ketika naik dan turun bukit dan bertemu jemaah lain. Talbiah umrah berhenti apabila mula tawaf; talbiah haji berhenti apabila mula melontar Jamrah Aqabah.","Men say it aloud, women softly. Repeat it all along the way, going up and down hills and when meeting others. For umrah stop when tawaf begins; for hajj stop when you start stoning Jamrat al-Aqabah."],
    w:["Dari niat hingga tawaf (umrah) atau lontar Aqabah (haji)","From niat until tawaf (umrah) or stoning Aqabah (hajj)"], doa:["talbiah","selawat","ridha","safar"], src:"Sahih al-Bukhari 1544"},
  larangan:{pl:"birali", k:"W", t:["Menjaga larangan ihram","Keeping the ihram rules"],
    d:["Semasa ihram: lelaki tidak boleh memakai pakaian berjahit yang melingkungi badan atau menutup kepala; wanita tidak boleh menutup muka atau memakai sarung tangan. Semua tidak boleh memakai wangian, meminyakkan rambut, mencabut atau memotong rambut dan kuku, memburu binatang darat, memotong pokok di Tanah Haram, berkahwin atau mengahwinkan, dan bersentuhan suami isteri. Melanggar larangan dikenakan dam. Lihat Rujukan untuk jenis dam.","While in ihram: men may not wear stitched clothing that wraps the body or cover the head; women may not cover the face or wear gloves. Nobody may use perfume, oil the hair, pluck or cut hair or nails, hunt land animals, cut trees in the Haram, marry or conduct a marriage, or have intimate contact. Breaking a rule makes dam due. See Reference for the types of dam."],
    w:["Sepanjang dalam ihram","All the time you are in ihram"], src:"Sahih al-Bukhari 1542; Sahih Muslim 1409"},
  tanim:{pl:"tanim", k:"W", t:["Ke Tan'im untuk umrah","To Tan'im for umrah"],
    d:["Orang yang berada di Makkah dan mahu berumrah mesti keluar ke tanah halal untuk berniat, seperti Tan'im (Masjid Aisyah) atau Ji'ranah. Mandi, solat sunat ihram dan niat umrah di sana, kemudian kembali ke Masjidil Haram.","Someone in Makkah who wants to do umrah must go out to land outside the Haram to make niat, such as Tan'im (Aisha Mosque) or Ji'ranah. Bathe, pray the ihram sunnah and make niat for umrah there, then return to al-Masjid al-Haram."],
    w:["Selepas selesai haji (bagi haji ifrad)","After the hajj (for hajj ifrad)"], doa:["niat_u","talbiah"], src:"Sahih al-Bukhari 1556"},
  // ---------- Makkah ----------
  masuk:{pl:"haram", k:"S", t:["Masuk Masjidil Haram","Entering al-Masjid al-Haram"],
    d:["Masuk dengan kaki kanan dan baca doa masuk masjid. Apabila mula melihat Kaabah, angkat tangan dan berdoa. Bagi yang hendak tawaf, tawaf itulah tahiyatul masjid.","Enter with your right foot and say the doa for entering the mosque. When you first see the Kaabah, raise your hands and make doa. For someone about to do tawaf, the tawaf is the greeting of the mosque."],
    w:["Setibanya di Makkah","On arrival in Makkah"], doa:["masuk","lihat_kaabah"]},
  tawaf_u:{pl:"kaabah", k:"R", t:["Tawaf umrah (7 pusingan)","Umrah tawaf (7 rounds)"],
    d:["Mula di garisan Hajar Aswad dengan Kaabah di sebelah kiri. Setiap pusingan bermula dan berakhir di Hajar Aswad. Lelaki sunat idhtiba' (bahu kanan terbuka) sepanjang tawaf, dan ramal (berjalan cepat dengan langkah pendek) pada tiga pusingan pertama. Tiada doa khusus bagi setiap pusingan: bacalah zikir, doa atau al-Quran.","Start at the Black Stone line with the Kaabah on your left. Each round begins and ends at the Black Stone. Men keep the right shoulder bare (idtiba') throughout, and walk briskly with short steps (raml) for the first three rounds. There is no set doa for each round: say dhikr, doa or Quran."],
    w:["Selepas tiba, dalam keadaan berwuduk","After arriving, with wudhu"], doa:["niat_tawaf","istilam","rabbana"], act:"tawaf",
    tip:[["Syarat sah: suci daripada hadas dan najis, tutup aurat, Kaabah di kiri, tujuh pusingan, di luar Hijir Ismail, di dalam masjid.","Conditions: free of hadas and najis, aurat covered, Kaabah on the left, seven rounds, outside the Hijr, inside the mosque."]], src:"Sahih Muslim 1218"},
  tawaf_q:{pl:"kaabah", k:"S", t:["Tawaf qudum (tawaf selamat datang)","Tawaf al-qudum (arrival tawaf)"],
    d:["Bagi haji ifrad dan qiran, tawaf pertama setibanya di Makkah ialah tawaf qudum, hukumnya sunat. Caranya sama dengan tawaf lain: tujuh pusingan bermula di Hajar Aswad, Kaabah di sebelah kiri.","For hajj ifrad and qiran, the first tawaf on arrival is the arrival tawaf, which is sunnah. It is done like any tawaf: seven rounds from the Black Stone, Kaabah on your left."],
    w:["Setibanya di Makkah, sebelum wukuf","On arrival in Makkah, before Arafah"], doa:["istilam","rabbana"], act:"tawaf"},
  yamani:{pl:"yamani", k:"S", t:["Rukun Yamani","The Yamani corner"],
    d:["Sentuh Rukun Yamani dengan tangan jika mudah, tanpa mengucupnya. Jika sesak, teruskan berjalan tanpa isyarat. Dari sini hingga Hajar Aswad, baca doa Rabbana atina.","Touch the Yamani corner with your hand if it is easy, without kissing it. If it is crowded, carry on without pointing. From here to the Black Stone, say Rabbana atina."],
    w:["Setiap pusingan tawaf","Every round of tawaf"], doa:["rabbana"], src:"Sahih al-Bukhari 1609"},
  multazam:{pl:"multazam", k:"S", t:["Berdoa di Multazam","Doa at al-Multazam"],
    d:["Multazam ialah dinding di antara Hajar Aswad dan pintu Kaabah. Ia tempat mustajab berdoa. Berdoalah dengan apa sahaja hajat jika tidak terlalu sesak.","Al-Multazam is the wall between the Black Stone and the Kaabah door. It is a place where doa is answered. Ask for anything you need if it is not too crowded."],
    w:["Selepas tawaf, jika mampu","After tawaf, if you can"], doa:["afiyah"], src:"Sunan Abi Dawud 1899"},
  maqam:{pl:"maqam", k:"S", t:["Solat sunat tawaf di belakang Maqam Ibrahim","Tawaf prayer behind Maqam Ibrahim"],
    d:["Selepas tawaf, tutup semula bahu kanan dan solat dua rakaat di belakang Maqam Ibrahim. Jika sesak, solat di mana-mana dalam masjid.","After tawaf, cover the right shoulder again and pray two rakaat behind Maqam Ibrahim. If crowded, pray anywhere in the mosque."],
    sl:["2 rakaat sunat tawaf","2 rakaat tawaf sunnah"], w:["Selepas setiap tawaf","After every tawaf"], doa:["maqam","solat_tawaf"], act:"solat"},
  zamzam:{pl:"zamzam", k:"S", t:["Minum air Zamzam","Drinking Zamzam water"],
    d:["Minum air Zamzam sambil menghadap kiblat, berdiri atau duduk, dalam tiga teguk, dan berdoa dengan niat yang baik.","Drink Zamzam facing the qibla, standing or sitting, in three sips, with a good intention and doa."],
    w:["Selepas solat sunat tawaf","After the tawaf prayer"], doa:["zamzam"]},
  saie:{pl:"safa", k:"R", t:["Sa'ie umrah (7 kali)","Umrah sa'i (7 lengths)"],
    d:["Mula di Bukit Safa dan berakhir di Marwah. Safa ke Marwah dikira satu, Marwah ke Safa dikira dua, sehingga tujuh. Naik sedikit ke bukit, hadap Kaabah dan berzikir. Lelaki berlari-lari anak di antara lampu hijau. Sa'ie mesti selepas tawaf yang sah. Wuduk tidak wajib tetapi digalakkan.","Start at Safa and finish at Marwah. Safa to Marwah counts as one, Marwah back to Safa as two, up to seven. Climb a little, face the Kaabah and say the dhikr. Men jog between the green lights. Sa'i must come after a valid tawaf. Wudhu is not required but recommended."],
    w:["Selepas tawaf","After tawaf"], doa:["safa","safa_zikir","hijau"], act:"saie", src:"Sahih Muslim 1218"},
  saie_q:{pl:"safa", k:"R", t:["Sa'ie haji (selepas tawaf qudum)","Hajj sa'i (after the arrival tawaf)"],
    d:["Bagi haji ifrad dan qiran, sa'ie haji boleh dibuat selepas tawaf qudum. Jika dibuat sekarang, tidak perlu diulang selepas tawaf ifadah. Jangan bercukur: kita masih dalam ihram haji.","For hajj ifrad and qiran, the hajj sa'i may be done after the arrival tawaf. If done now, it is not repeated after tawaf al-ifadah. Do not cut your hair: you are still in hajj ihram."],
    w:["Selepas tawaf qudum (atau selepas tawaf ifadah)","After the arrival tawaf (or after tawaf al-ifadah)"], doa:["safa","safa_zikir","hijau"], act:"saie"},
  cukur_u:{pl:"gunting", k:"R", t:["Bercukur atau bergunting (tahallul umrah)","Shaving or trimming (end of umrah)"],
    d:["Lelaki afdal bercukur seluruh kepala, atau menggunting. Wanita memotong hujung rambut kira-kira satu ruas jari. Sekurang-kurangnya tiga helai rambut. Selepas ini umrah selesai dan semua larangan ihram terangkat. Alhamdulillah!","Men ideally shave the whole head, or trim. Women cut about a fingertip's length from the ends. At least three hairs. Your umrah is now complete and all ihram rules are lifted. Alhamdulillah!"],
    w:["Selepas sa'ie","After sa'i"], doa:["cukur"], act:"cukur"},
  wada_u:{pl:"kaabah", k:"W", t:["Tawaf wada' (tawaf selamat tinggal)","Tawaf al-wada' (farewell tawaf)"],
    d:["Sebelum meninggalkan Makkah, lakukan tawaf wada' tujuh pusingan tanpa sa'ie. Dalam mazhab Syafi'i ia wajib bagi sesiapa yang hendak meninggalkan Makkah ke jarak jauh; sebahagian ulama berpendapat ia sunat bagi jemaah umrah. Wanita yang haid atau nifas dikecualikan.","Before leaving Makkah, do seven rounds of farewell tawaf with no sa'i. In the Shafi'i school it is wajib for anyone leaving Makkah on a long journey; some scholars hold it is sunnah for umrah pilgrims. Women in menses or post-natal bleeding are excused."],
    w:["Sebaik sebelum bertolak pulang","Just before leaving"], doa:["wada","keluar"], act:"tawaf", src:"Sahih Muslim 1327; Sahih al-Bukhari 1755"},
  // ---------- Hajj days ----------
  tarwiyah_t:{pl:"hotel", k:"R", t:["8 Zulhijjah: niat ihram haji di Makkah","8 Dhul Hijjah: niat for hajj in Makkah"],
    d:["Hari Tarwiyah. Jemaah haji tamattu' berihram semula dari tempat tinggal di Makkah dan berniat haji. Sunat ke Mina dan bermalam di sana pada malam 9 Zulhijjah. Kebanyakan jemaah Malaysia dibawa terus ke Arafah oleh Tabung Haji.","The day of Tarwiyah. Tamattu' pilgrims enter ihram again from where they stay in Makkah and make niat for hajj. It is sunnah to go to Mina and spend the night there. Most Malaysian pilgrims are taken straight to Arafah by Tabung Haji."],
    w:["8 Zulhijjah","8 Dhul Hijjah"], sl:["Di Mina: Zohor, Asar, Maghrib, Isyak dan Subuh, diqasarkan tanpa jamak","At Mina: Zuhr, Asr, Maghrib, Isha and Fajr, shortened but not combined"], doa:["niat_h","talbiah"], src:"Sahih Muslim 1218"},
  tarwiyah_i:{pl:"mina", k:"S", t:["8 Zulhijjah: ke Mina","8 Dhul Hijjah: to Mina"],
    d:["Hari Tarwiyah. Jemaah ifrad dan qiran masih dalam ihram, jadi tiada niat baharu. Sunat ke Mina dan bermalam di sana pada malam 9 Zulhijjah sambil bertalbiah.","The day of Tarwiyah. Ifrad and qiran pilgrims are still in ihram, so there is no new niat. It is sunnah to go to Mina and spend the night there, saying the talbiyah."],
    w:["8 Zulhijjah","8 Dhul Hijjah"], sl:["Solat diqasarkan tanpa jamak","Prayers shortened but not combined"], doa:["talbiah"]},
  arafah_go:{pl:"namirah", k:"S", t:["9 Zulhijjah: ke Arafah","9 Dhul Hijjah: to Arafah"],
    d:["Selepas matahari terbit, bertolak ke Arafah sambil bertalbiah. Sunat mandi untuk wukuf. Selepas tergelincir matahari, dengar khutbah Arafah dan solat Zohor dan Asar secara jamak taqdim dan qasar.","After sunrise, set off for Arafah saying the talbiyah. It is sunnah to bathe for the standing. After midday, listen to the Arafah sermon and pray Zuhr and Asr combined early and shortened."],
    w:["9 Zulhijjah pagi","Morning of 9 Dhul Hijjah"], sl:["Zohor dan Asar: jamak taqdim, qasar (2 + 2)","Zuhr and Asr: combined early, shortened (2 + 2)"], doa:["talbiah"], src:"Sahih Muslim 1218"},
  wukuf:{pl:"arafah", k:"R", t:["Wukuf di Arafah","Standing at Arafah"],
    d:["Rukun haji yang paling utama: \"Haji itu Arafah.\" Berada di dalam sempadan Arafah walaupun seketika, antara tergelincir matahari 9 Zulhijjah hingga terbit fajar 10 Zulhijjah. Afdal berada sehingga matahari terbenam. Hadap kiblat, angkat tangan, perbanyak zikir, istighfar, selawat dan doa untuk diri, keluarga dan umat. Mendaki Jabal Rahmah bukan amalan khusus haji.","The most important rukun: \"Hajj is Arafah.\" Be inside the Arafah boundary, even for a moment, between midday on 9 Dhul Hijjah and dawn on the 10th. Staying until sunset is best. Face the qibla, raise your hands and make plenty of dhikr, istighfar, salawat and doa for yourself, your family and the ummah. Climbing Jabal al-Rahmah is not a hajj rite."],
    w:["9 Zulhijjah, dari gelincir matahari hingga terbenam (sah hingga fajar 10)","9 Dhul Hijjah, from midday to sunset (valid until dawn on the 10th)"], doa:["arafah","istighfar","rabbana"], act:"wukuf", src:"Sunan at-Tirmizi 889, 3585"},
  muzdalifah:{pl:"muzdalifah", k:"W", t:["Bermalam di Muzdalifah","The night at Muzdalifah"],
    d:["Selepas matahari terbenam, bertolak dengan tenang ke Muzdalifah. Solat Maghrib dan Isyak secara jamak ta'khir. Wajib berada di Muzdalifah walaupun seketika selepas tengah malam. Sunat mengutip batu kecil sebesar biji kacang: 7 untuk Jamrah Aqabah, atau 70 untuk semua hari (49 jika nafar awal).","After sunset, move calmly to Muzdalifah. Pray Maghrib and Isha combined late. You must be in Muzdalifah, even for a moment, after midnight. It is sunnah to pick small pebbles the size of a chickpea: 7 for Jamrat al-Aqabah, or 70 for all days (49 if leaving early)."],
    w:["Malam 10 Zulhijjah, selepas tengah malam","The night of 10 Dhul Hijjah, after midnight"], sl:["Maghrib dan Isyak: jamak ta'khir, Isyak diqasar (3 + 2)","Maghrib and Isha: combined late, Isha shortened (3 + 2)"], doa:["talbiah","istighfar"], act:"pebbles", src:"Sahih Muslim 1218; Sunan an-Nasa'i 3057"},
  masyar:{pl:"masyar", k:"S", t:["Berhenti di Masy'aril Haram","Stopping at al-Mash'ar al-Haram"],
    d:["Selepas solat Subuh awal waktu, berhenti di Masy'aril Haram (atau di mana-mana di Muzdalifah), hadap kiblat dan berzikir hingga langit cerah. Bertolak ke Mina sebelum matahari terbit.","After praying Fajr early, stop at al-Mash'ar al-Haram (or anywhere in Muzdalifah), face the qibla and make dhikr until it is bright. Leave for Mina before sunrise."],
    w:["Subuh 10 Zulhijjah","Fajr on 10 Dhul Hijjah"], doa:["masyar","takbir"]},
  aqabah:{pl:"aqabah", k:"W", t:["10 Zulhijjah: melontar Jamrah Aqabah","10 Dhul Hijjah: stoning Jamrat al-Aqabah"],
    d:["Hari Raya Aidiladha. Lontar tujuh biji batu satu demi satu ke Jamrah Aqabah sahaja, sambil bertakbir. Berhenti bertalbiah apabila mula melontar dan mula bertakbir raya. Waktu bermula selepas tengah malam 10 Zulhijjah; afdal selepas matahari terbit. Tiada doa berdiri selepas lontaran ini.","Eid al-Adha. Throw seven pebbles one by one at Jamrat al-Aqabah only, saying takbir. Stop the talbiyah when you start and begin the Eid takbir. The time starts after midnight on the 10th; after sunrise is best. There is no standing doa after this one."],
    w:["10 Zulhijjah, afdal pagi","10 Dhul Hijjah, morning is best"], doa:["lontar","takbir"], act:"lontar1", src:"Sahih al-Bukhari 1544, 1751"},
  hadyu:{pl:"korban", k:"D", t:["Dam haji tamattu' dan qiran","The dam for tamattu' and qiran"],
    d:["Jemaah tamattu' dan qiran wajib membayar dam: menyembelih seekor kambing di Tanah Haram (biasanya diuruskan melalui Tabung Haji atau bank). Jika tidak mampu, berpuasa 10 hari: 3 hari semasa haji dan 7 hari selepas pulang ke tanah air.","Tamattu' and qiran pilgrims must pay dam: slaughter one sheep or goat in the Haram (usually arranged through Tabung Haji or a bank). If you cannot, fast 10 days: 3 during hajj and 7 after returning home."],
    w:["Afdal 10 Zulhijjah; boleh hingga akhir hari tasyrik","Best on 10 Dhul Hijjah; allowed until the end of the tashriq days"], doa:["sembelih"], src:"Al-Baqarah 2:196"},
  korban_s:{pl:"korban", k:"S", t:["Korban (sunat)","Sacrifice (sunnah)"],
    d:["Jemaah haji ifrad tidak dikenakan dam tamattu'. Menyembelih korban pada Hari Raya adalah sunat.","Ifrad pilgrims owe no tamattu' dam. Offering a sacrifice on Eid is sunnah."],
    w:["10 hingga 13 Zulhijjah","10 to 13 Dhul Hijjah"], doa:["sembelih"]},
  cukur_h:{pl:"gunting", k:"R", t:["Bercukur atau bergunting (tahallul awal)","Shaving or trimming (first release)"],
    d:["Selepas melontar Jamrah Aqabah, bercukur (afdal bagi lelaki) atau bergunting sekurang-kurangnya tiga helai. Apabila dua daripada tiga perkara selesai (melontar Aqabah, bercukur, tawaf ifadah dengan sa'ie), berlaku tahallul awal: semua larangan ihram terangkat kecuali yang berkaitan suami isteri dan nikah. Boleh bercukur di Mina.","After stoning Jamrat al-Aqabah, shave (best for men) or trim at least three hairs. When two of the three acts are done (stoning Aqabah, the haircut, tawaf al-ifadah with sa'i), the first release happens: all ihram rules are lifted except those about marriage and intimacy. You may have the haircut in Mina."],
    w:["Dari tengah malam 10 Zulhijjah","From midnight on 10 Dhul Hijjah"], doa:["cukur","takbir"], act:"cukur"},
  ifadah:{pl:"kaabah", k:"R", t:["Tawaf ifadah (tawaf haji)","Tawaf al-ifadah (the hajj tawaf)"],
    d:["Rukun haji. Tujuh pusingan seperti tawaf lain. Jika belum sa'ie haji, lakukan sa'ie selepas tawaf ini. Selepas ketiga-tiga perkara selesai, berlaku tahallul thani: semua larangan ihram terangkat. Wanita yang haid menunggu sehingga suci.","A rukun of hajj. Seven rounds like any tawaf. If you have not done the hajj sa'i yet, do it after this tawaf. When all three acts are done, the second release happens: every ihram rule is lifted. A woman in menses waits until she is clean."],
    w:["Dari tengah malam 10 Zulhijjah, tiada had akhir (afdal 10 Zulhijjah)","From midnight on 10 Dhul Hijjah, no end time (best on the 10th)"], doa:["istilam","rabbana"], act:"tawaf", src:"Al-Hajj 22:29; Sahih Muslim 1218"},
  saie_h:{pl:"safa", k:"R", t:["Sa'ie haji","The hajj sa'i"],
    d:["Jemaah tamattu' wajib sa'ie haji selepas tawaf ifadah, tujuh kali dari Safa ke Marwah, sama seperti sa'ie umrah.","Tamattu' pilgrims do the hajj sa'i after tawaf al-ifadah, seven lengths from Safa to Marwah, the same as the umrah sa'i."],
    w:["Selepas tawaf ifadah","After tawaf al-ifadah"], doa:["safa","safa_zikir","hijau"], act:"saie"},
  mabit:{pl:"mina", k:"W", t:["Bermalam di Mina (hari tasyrik)","The nights in Mina (tashriq days)"],
    d:["Wajib bermalam di Mina pada malam 11 dan 12 Zulhijjah (dan malam 13 bagi nafar thani), iaitu berada di Mina lebih separuh malam. Isi masa dengan solat, zikir, takbir, membaca al-Quran dan berehat. Hari-hari tasyrik ialah hari makan, minum dan zikir; tidak boleh berpuasa.","You must spend the nights of 11 and 12 Dhul Hijjah (and the 13th if staying on) in Mina, being there for most of the night. Fill the time with prayer, dhikr, takbir, Quran and rest. The tashriq days are days of eating, drinking and remembering Allah; fasting is not allowed."],
    w:["Malam 11, 12 (dan 13) Zulhijjah","Nights of 11, 12 (and 13) Dhul Hijjah"], sl:["Solat diqasarkan pada waktunya","Prayers shortened, each in its own time"], doa:["takbir"], src:"Sahih Muslim 1141"},
  lontar3:{pl:"jamrat", k:"W", t:["11 hingga 13 Zulhijjah: melontar tiga jamrah","11 to 13 Dhul Hijjah: stoning the three jamarat"],
    d:["Setiap hari selepas tergelincir matahari, lontar tujuh batu ke setiap jamrah mengikut tertib: Ula, kemudian Wusta, kemudian Aqabah. Selepas Ula dan Wusta, ke tepi, hadap kiblat, angkat tangan dan berdoa panjang. Selepas Aqabah, terus beredar. Boleh mewakilkan lontaran jika uzur.","Each day after midday, throw seven pebbles at each jamrah in order: al-Ula, then al-Wusta, then al-Aqabah. After al-Ula and al-Wusta, step aside, face the qibla, raise your hands and make a long doa. After al-Aqabah, leave straight away. Someone who is unwell may appoint another to throw for them."],
    w:["11, 12 (dan 13) Zulhijjah, selepas zohor","11, 12 (and 13) Dhul Hijjah, after midday"], doa:["lontar","rabbana","afiyah"], act:"lontar3", src:"Sahih al-Bukhari 1751, 1753"},
  nafar:{pl:"mina", k:"A", t:["Nafar awal atau nafar thani","Leaving early or staying on"],
    d:["Nafar awal: selepas melontar pada 12 Zulhijjah, keluar dari Mina sebelum matahari terbenam; tidak perlu bermalam dan melontar pada 13. Nafar thani: bermalam di Mina malam 13 dan melontar pada 13 Zulhijjah, ini lebih afdal. Jika masih di Mina ketika matahari terbenam 12 Zulhijjah, wajib nafar thani.","Leaving early: after stoning on 12 Dhul Hijjah, leave Mina before sunset; no night or stoning on the 13th. Staying on: spend the 13th night in Mina and stone on the 13th, which is better. If you are still in Mina at sunset on the 12th, you must stay on."],
    w:["12 atau 13 Zulhijjah","12 or 13 Dhul Hijjah"], src:"Al-Baqarah 2:203"},
  wada:{pl:"kaabah", k:"W", t:["Tawaf wada' (tawaf selamat tinggal)","Tawaf al-wada' (farewell tawaf)"],
    d:["Ibadat terakhir sebelum meninggalkan Makkah: tujuh pusingan tanpa sa'ie. Wajib; jika ditinggalkan dikenakan dam. Wanita yang haid atau nifas dikecualikan. Selepas itu jangan berlama-lama di Makkah. Berdoalah agar dapat kembali lagi.","The last act before leaving Makkah: seven rounds with no sa'i. It is wajib; missing it makes dam due. Women in menses or post-natal bleeding are excused. Do not linger in Makkah afterwards. Ask Allah to let you come back."],
    w:["Sebaik sebelum bertolak pulang","Just before leaving Makkah"], doa:["wada","keluar"], act:"tawaf", src:"Sahih Muslim 1327; Sahih al-Bukhari 1755"},
  // ---------- Madinah ----------
  nabawi_in:{pl:"nabawi", k:"S", t:["Masuk Masjid Nabawi","Entering the Prophet's Mosque"],
    d:["Ziarah Madinah bukan rukun atau wajib haji, tetapi sangat digalakkan. Masuk dengan kaki kanan, baca doa masuk masjid dan solat dua rakaat tahiyatul masjid. Rendahkan suara: ini masjid Rasulullah ﷺ.","Visiting Madinah is not part of hajj, but it is highly encouraged. Enter with your right foot, say the doa and pray two rakaat to greet the mosque. Keep your voice low: this is the Prophet's ﷺ mosque."],
    w:["Bila-bila masa","Any time"], sl:["2 rakaat tahiyatul masjid","2 rakaat greeting the mosque"], doa:["masuk","nabawi"], act:"solat", src:"Sahih al-Bukhari 1189"},
  raudhah:{pl:"raudhah", k:"S", t:["Solat dan berdoa di Raudhah","Praying in the Raudhah"],
    d:["Raudhah ialah kawasan di antara mimbar dan rumah Nabi ﷺ, ditandai permaidani hijau. Masuk mengikut giliran yang ditetapkan (biasanya melalui aplikasi Nusuk), solat sunat dan berdoa dengan tenang, kemudian beri ruang kepada orang lain.","The Raudhah is the area between the pulpit and the Prophet's ﷺ house, marked by green carpet. Enter at your set turn (usually booked in the Nusuk app), pray and make doa calmly, then make room for others."],
    w:["Mengikut giliran","At your booked time"], sl:["Solat sunat mutlak","Voluntary prayer"], doa:["raudhah","afiyah"], act:"solat"},
  salam:{pl:"makam", k:"S", t:["Salam kepada Rasulullah ﷺ dan dua sahabat","Greeting the Prophet ﷺ and his two companions"],
    d:["Berjalan perlahan melalui hadapan makam, ucap salam kepada Rasulullah ﷺ dengan suara rendah, kemudian kepada Abu Bakar dan Umar r.a. Berdoa kepada Allah sambil menghadap kiblat, bukan menghadap makam.","Walk slowly past the resting place, greet the Prophet ﷺ softly, then Abu Bakr and Umar. Make doa to Allah facing the qibla, not the grave."],
    w:["Bila-bila masa dibuka","Whenever it is open"], doa:["salam_nabi","salam_sahabat"]},
  baqi:{pl:"baqi", k:"S", t:["Ziarah Perkuburan Baqi'","Visiting al-Baqi'"],
    d:["Baqi' ialah perkuburan ramai sahabat dan ahli keluarga Nabi ﷺ. Ucap salam dan doakan mereka. Lelaki boleh masuk pada waktu yang dibuka.","Al-Baqi' is where many companions and members of the Prophet's ﷺ family are buried. Greet them and pray for them. Men may enter at the opening times."],
    w:["Biasanya selepas Subuh dan Asar","Usually after Fajr and Asr"], doa:["kubur"], src:"Sahih Muslim 975"},
  quba:{pl:"quba", k:"S", t:["Solat di Masjid Quba","Praying at Quba Mosque"],
    d:["Masjid pertama yang dibina oleh Nabi ﷺ selepas hijrah. Berwuduk dari tempat tinggal, kemudian solat dua rakaat di sana: pahalanya seperti umrah.","The first mosque the Prophet ﷺ built after the hijrah. Make wudhu where you stay, then pray two rakaat there: the reward is like umrah."],
    w:["Bila-bila masa (Nabi ﷺ selalu ke sana pada hari Sabtu)","Any time (the Prophet ﷺ often went on Saturdays)"], sl:["2 rakaat","2 rakaat"], doa:["quba"], act:"solat", src:"Sahih al-Bukhari 1193"},
  uhud:{pl:"uhud", k:"S", t:["Ziarah Bukit Uhud","Visiting Mount Uhud"],
    d:["Di kaki Bukit Uhud terletak makam para syuhada Uhud, termasuk Saidina Hamzah r.a. Ucap salam dan doakan mereka. Nabi ﷺ bersabda: \"Uhud ialah bukit yang mencintai kita dan kita mencintainya.\"","At the foot of Mount Uhud are the graves of the martyrs of Uhud, including Hamzah. Greet them and pray for them. The Prophet ﷺ said: \"Uhud is a mountain that loves us and we love it.\""],
    w:["Bila-bila masa","Any time"], doa:["kubur"], src:"Sahih al-Bukhari 4083"},
  nabawi_out:{pl:"nabawi", k:"S", t:["Keluar dari Masjid Nabawi","Leaving the Prophet's Mosque"],
    d:["Keluar dengan kaki kiri dan baca doa keluar masjid. Berdoalah agar Allah menerima ziarah kita dan menjemput kita kembali.","Leave with your left foot and say the doa for leaving the mosque. Ask Allah to accept your visit and invite you back."],
    w:["Setiap kali keluar","Every time you leave"], doa:["keluar"]}
};

