  masa:{t:["Kawasan lampu hijau: lelaki sunat berlari-lari anak, wanita berjalan seperti biasa.","The green-light zone: men jog lightly, women walk normally."], doa:["hijau"]},
  marwah:{t:["Di Marwah, buat seperti di Safa: hadap Kaabah, bertakbir dan berdoa. Sa'ie tamat di Marwah pada kali ketujuh.","On Marwah, do as on Safa: face the Kaabah, say takbir and make doa. Sa'i ends at Marwah on the seventh length."], doa:["safa_zikir"]},
  rahmah:{t:["Jabal Rahmah ialah bukit kecil di Arafah. Wukuf sah di mana-mana dalam sempadan Arafah; mendakinya bukan amalan haji.","Jabal al-Rahmah is a small hill in Arafah. Wukuf is valid anywhere inside Arafah; climbing it is not a hajj rite."], doa:["arafah"]},
  hotel:{t:["Sebelum keluar, semak barang: kain ihram, ubat, botol air dan beg batu. Baca doa naik kenderaan.","Before leaving, check your things: ihram, medicine, water bottle and pebble bag. Say the travel doa."], doa:["safar"]},
  korban:{t:["Dam dan korban disembelih oleh pihak berkuasa; jemaah biasanya membayar melalui Tabung Haji.","Dam and sacrifices are slaughtered by the authorities; pilgrims usually pay through Tabung Haji."], doa:["sembelih"]}
